import React, { useState } from 'react';
import ProjectModal from '../ProjectModal/ProjectModal';
import './Portfolio.css';

const Portfolio = () => {
    const [selectedProject, setSelectedProject] = useState(null);
    const [showModal, setShowModal] = useState(false);
    const [filter, setFilter] = useState('*');

    const projects = [
        {
            id: 1,
            title: "INTERFACE MOBILE",
            category: "filter-app",
            description: "Aplicativo mobile desenvolvido em React Native com interface moderna e responsiva.",
            technologies: ["React Native", "JavaScript", "Firebase"],
            images: ["/assets/img/thumbnail/INTERFACE-MOBILE.png"],
            details: "portfolio-detailsInterfaceMobile.html"
        },
        {
            id: 2,
            title: "SISTEMA WEB PARA A GESTÃO DE FARMÁCIA",
            category: "filter-web",
            description: "Sistema web completo para gestão de farmácias com controle de estoque e vendas.",
            technologies: ["PHP", "MySQL", "JavaScript", "Bootstrap"],
            images: ["/assets/img/thumbnail/SISTEMA-WEB-PARA-A-GESTÃO-DE-FARMACIA.png"],
            details: "portfolio-detailsSiscure.html"
        },
        {
            id: 3,
            title: "PROJETO EM REACT NATIVE",
            category: "filter-app",
            description: "Aplicativo mobile desenvolvido com React Native e integração com APIs.",
            technologies: ["React Native", "Node.js", "MongoDB"],
            images: ["/assets/img/thumbnail/PROJETO-EM-REACT-NATIVE.png"],
            details: "portfolio-detailsProjetoEmReactNative.html"
        },
        {
            id: 4,
            title: "BEEP SAÚDE FRONT END",
            category: "filter-web",
            description: "Front-end para sistema de saúde com agendamento de consultas e telemedicina.",
            technologies: ["React", "TypeScript", "Styled Components"],
            images: ["/assets/img/thumbnail/BEEP-SAUDE-FRONT-END.png"],
            details: "portfolio-detailsBeep.html"
        },
        {
            id: 5,
            title: "PROJETO CRUD",
            category: "filter-web",
            description: "Sistema completo CRUD (Create, Read, Update, Delete) para gerenciamento de dados.",
            technologies: ["PHP", "MySQL", "JavaScript"],
            images: ["/assets/img/portfolio/thumbnail/PROJETO-CRUD.png"],
            details: "portfolio-detailsProjetoCrud.html"
        },
        {
            id: 6,
            title: "WEB SCRAPING",
            category: "filter-card",
            description: "Sistema de extração de dados de websites usando técnicas de web scraping.",
            technologies: ["Python", "BeautifulSoup", "Selenium"],
            images: ["/assets/img/portfolio/thumbnail/WEB-SCRAPING.png"],
            details: "portfolio-detailsWebScraping.html"
        },
        {
            id: 7,
            title: "EXTRATOR DE TEXTO DE PDF",
            category: "filter-card",
            description: "Ferramenta para extrair texto de arquivos PDF de forma eficiente.",
            technologies: ["Python", "PyPDF2", "Tkinter"],
            images: ["/assets/img/portfolio/thumbnail/Extrator-de-Texto-de-PDF.png"],
            details: "portfolio-detailsExtrator.html"
        },
        {
            id: 8,
            title: "WEB TEST AUTOMATION",
            category: "filter-card",
            description: "Sistema de automação de testes para aplicações web.",
            technologies: ["Selenium", "Java", "JUnit"],
            images: ["/assets/img/portfolio/thumbnail/WEB-TEST-AUTOMATION.png"],
            details: "portfolio-detailsweb-test-automation.html"
        },
        {
            id: 9,
            title: "GERENCIAMENTO DE PROJETOS",
            category: "filter-web",
            description: "Sistema local para gerenciamento de projetos em PHP e React.",
            technologies: ["PHP", "React", "MySQL", "Node.js"],
            images: ["/assets/img/portfolio/thumbnail/Localhost.png"],
            details: "portfolio-detailsLocalhost.html"
        },
        {
            id: 10,
            title: "GUIA DE PAGAMENTO",
            category: "filter-web",
            description: "Sistema para gestão e orientação de processos de pagamento.",
            technologies: ["JavaScript", "HTML5", "CSS3"],
            images: ["/assets/img/portfolio/thumbnail/Guia-de-pagamento.png"],
            details: "portfolio-detailsGuiaDePagamento.html"
        },
        {
            id: 11,
            title: "ROCKET CHAT",
            category: "filter-web",
            description: "Implementação e customização de sistema de chat em tempo real.",
            technologies: ["Rocket.Chat", "JavaScript", "MongoDB"],
            images: ["/assets/img/portfolio/thumbnail/Rocket-chat.png"],
            details: "portfolio-detailsRocket.html"
        }
    ];

    const filteredProjects = filter === '*'
        ? projects
        : projects.filter(project => project.category === filter);

    const handleProjectClick = (project) => {
        setSelectedProject(project);
        setShowModal(true);
    };

    const handleCloseModal = () => {
        setShowModal(false);
        setSelectedProject(null);
    };

    return (
        <section id="portfolio" className="portfolio section-bg bg-dark text-white">
            <div className="container">
                <div className="section-title">
                    <h2 className="text-white">Projetos</h2>
                </div>

                {/* Filtros */}
                <div className="row" data-aos="fade-up">
                    <div className="col-lg-12 d-flex justify-content-center">
                        <ul id="portfolio-flters">
                            <li
                                className={filter === '*' ? 'filter-active' : ''}
                                onClick={() => setFilter('*')}
                            >
                                Todos
                            </li>
                            <li
                                className={filter === 'filter-app' ? 'filter-active' : ''}
                                onClick={() => setFilter('filter-app')}
                            >
                                React Native
                            </li>
                            <li
                                className={filter === 'filter-card' ? 'filter-active' : ''}
                                onClick={() => setFilter('filter-card')}
                            >
                                Node.js
                            </li>
                            <li
                                className={filter === 'filter-web' ? 'filter-active' : ''}
                                onClick={() => setFilter('filter-web')}
                            >
                                Web
                            </li>
                        </ul>
                    </div>
                </div>

                {/* Grid de Projetos */}
                <div className="row portfolio-container" data-aos="fade-up" data-aos-delay="100">
                    {filteredProjects.map(project => (
                        <div key={project.id} className="col-lg-4 col-md-6 portfolio-item">
                            <div className="portfolio-wrap" onClick={() => handleProjectClick(project)}>
                                <img
                                    src={project.images[0]}
                                    className="img-fluid"
                                    alt={project.title}
                                />
                                <div className="portfolio-links">
                                    <a href={project.images[0]} data-gallery="portfolioGallery" className="portfolio-lightbox">
                                        <i className="bx bx-plus"></i>
                                    </a>
                                    <a href="#" title="Mais Detalhes">
                                        <i className="bx bx-link"></i>
                                    </a>
                                </div>
                            </div>
                        </div>
                    ))}
                </div>

                {/* Modal */}
                <ProjectModal
                    show={showModal}
                    handleClose={handleCloseModal}
                    project={selectedProject}
                />
            </div>
        </section>
    );
};

export default Portfolio;
